-- First version of the data model (docs/raw/starting-point/2026-10-27-decisioni-db.md):
-- itineraries get an owner, a name and timestamps as columns; the days stay in a JSON document.
-- Every signed-in user reads every itinerary, only the owner changes or deletes it. anon reads nothing.

CREATE TABLE "public"."itineraries" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "owner_id"   uuid                     NOT NULL DEFAULT auth.uid() REFERENCES auth.users (id) ON DELETE CASCADE,
  "name"       text                     NOT NULL,
  "document"   jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now()
);

COMMENT ON TABLE "public"."itineraries" IS 'Itineraries: name and owner as columns, the rest (descriptions, photos, days) in document';

CREATE INDEX "itineraries_owner_id_idx" ON "public"."itineraries" (owner_id);

CREATE FUNCTION "public"."set_updated_at"() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = ''
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER "itineraries_set_updated_at"
  BEFORE UPDATE ON "public"."itineraries"
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- Move the existing itineraries, keeping their ids (and so their URLs).
-- They had no owner: they go to the first registered user.
DO $$
DECLARE
  old_count bigint;
  new_count bigint;
BEGIN
  INSERT INTO public.itineraries (id, owner_id, name, document, created_at, updated_at)
  OVERRIDING SYSTEM VALUE
  SELECT
    i.itinerary_json_id,
    (SELECT u.id FROM auth.users u ORDER BY u.created_at LIMIT 1),
    coalesce(i.itinerary_document ->> 'name', ''),
    coalesce(i.itinerary_document, '{}'::jsonb) - 'name' - 'id',
    i.created_at,
    i.created_at
  FROM public.itineraries_json i
  WHERE EXISTS (SELECT 1 FROM auth.users);

  SELECT count(*) INTO old_count FROM public.itineraries_json;
  SELECT count(*) INTO new_count FROM public.itineraries;
  IF old_count <> new_count THEN
    RAISE EXCEPTION 'itineraries: moved % of % rows (no user to own them?)', new_count, old_count;
  END IF;

  PERFORM setval(pg_get_serial_sequence('public.itineraries', 'id'), coalesce((SELECT max(id) FROM public.itineraries), 0) + 1, false);
END;
$$;

DROP TABLE "public"."itineraries_json";

ALTER TABLE "public"."itineraries" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "public"."itineraries" FROM "anon", "authenticated";
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE "public"."itineraries" TO "authenticated";

CREATE POLICY "Signed-in users read all itineraries" ON "public"."itineraries"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Signed-in users create their own itineraries" ON "public"."itineraries"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (owner_id = (SELECT auth.uid()));

CREATE POLICY "Owners update their itineraries" ON "public"."itineraries"
  FOR UPDATE
  TO "authenticated"
  USING (owner_id = (SELECT auth.uid()))
  WITH CHECK (owner_id = (SELECT auth.uid()));

CREATE POLICY "Owners delete their itineraries" ON "public"."itineraries"
  FOR DELETE
  TO "authenticated"
  USING (owner_id = (SELECT auth.uid()));

-- Categories: read-only for signed-in users (the select policy is in 20261027142257).
-- Also drop the names left over from the old "events" table.
REVOKE ALL ON TABLE "public"."categories" FROM "anon", "authenticated";
GRANT SELECT ON TABLE "public"."categories" TO "authenticated";
REVOKE ALL ON SEQUENCE "public"."events_category_id_seq" FROM "anon", "authenticated";

ALTER TABLE "public"."categories" RENAME CONSTRAINT "events_pkey" TO "categories_pkey";
ALTER SEQUENCE "public"."events_category_id_seq" RENAME TO "categories_category_id_seq";
